void calculate_tile_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                        OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                        OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                        OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 max_prec = 0;
    OPJ_UINT32 max_res = 0;
    OPJ_UINT32 dx_min = 0;
    OPJ_UINT32 dy_min = 0;

    /* Initialize tile coordinates based on tile number */
    *p_tx0 = p_tileno % p_image->numresolution;
    *p_tx1 = *p_tx0 + 1;
    *p_ty0 = p_tileno / p_image->numresolution;
    *p_ty1 = *p_ty0 + 1;

    for (compno = 0; compno < p_image->numcomps; compno++) {
        const opj_image_comp_t *comp = &p_image->comps[compno];

        for (resno = 0; resno < comp->resno; resno++) {
            OPJ_UINT32 dx = comp->dx;
            OPJ_UINT32 dy = comp->dy;
            OPJ_UINT32 prec = 1;

            dx >>= resno;
            dy >>= resno;

            if (dx < dx_min || dx_min == 0) {
                dx_min = dx;
            }
            if (dy < dy_min || dy_min == 0) {
                dy_min = dy;
            }

            prec++;
            if (prec > max_prec) {
                max_prec = prec;
            }
        }
    }

    *p_dx_min = dx_min;
    *p_dy_min = dy_min;
    *p_max_prec = max_prec;
    *p_max_res = max_res;
}

void calculate_tile_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                        OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                        OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                        OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;

    *p_tx0 = (OPJ_INT32)p_tileno % (OPJ_INT32)p_image->x_tile_number;
    *p_tx0 = (*p_tx0) * p_image->x0;
    *p_tx1 = *p_tx0 + p_image->x1 - p_image->x0;

    *p_ty0 = (OPJ_INT32)(p_tileno / (OPJ_INT32)p_image->x_tile_number);
    *p_ty0 = (*p_ty0) * p_image->y0;
    *p_ty1 = *p_ty0 + p_image->y1 - p_image->y0;

    *p_dx_min = 0;
    *p_dy_min = 0;
    *p_max_prec = 0;

    for (compno = 0; compno < p_image->numcomps; ++compno) {
        opj_tcp_t *tcp = &p_cp->tcp[p_cp->disto_alloc[compno]];
        opj_tccp_t *tccp = &tcp->tccps[compno];

        for (resno = 1; resno < tccp->numresolution; ++resno) {
            OPJ_UINT32 dx = tccp->resolutions[resno].dx;
            OPJ_UINT32 dy = tccp->resolutions[resno].dy;

            if (resno == 1) {
                if (*p_dx_min == 0 || dx < *p_dx_min) {
                    *p_dx_min = dx;
                }
                if (*p_dy_min == 0 || dy < *p_dy_min) {
                    *p_dy_min = dy;
                }
            }
            *p_max_prec = (OPJ_UINT32)OPJ_MAX(*p_max_prec, resno + 1);
        }
        *p_max_res = (OPJ_UINT32)OPJ_MAX(*p_max_res, tccp->numresolution);
    }
}

void calculate_tile_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                        OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                        OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                        OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 i, compno;
    OPJ_UINT32 x0, y0, x1, y1;
    OPJ_UINT32 dx_min = 0, dy_min = 0, max_prec = 0, max_res = 0;

    *p_tx0 = p_cp->tx0;
    *p_tx1 = p_cp->tx1;
    *p_ty0 = p_cp->ty0;
    *p_ty1 = p_cp->ty1;

    for (compno = 0; compno < p_image->numcomps; compno++) {
        opj_tcp_t *tcp = &p_cp->tcp[p_tileno];
        opj_tccp_t *tccp = &tcp->tccps[compno];

        for (i = 0; i < tccp->num_resolutions; ++i) {
            OPJ_UINT32 dx = tccp->resolutions[i].dx;
            OPJ_UINT32 dy = tccp->resolutions[i].dy;

            if (i == 0) {
                x0 = tccp->resolutions[i].x0;
                y0 = tccp->resolutions[i].y0;
                x1 = tccp->resolutions[i].x1;
                y1 = tccp->resolutions[i].y1;
            }

            if (dx < dx_min || dx_min == 0)
                dx_min = dx;
            if (dy < dy_min || dy_min == 0)
                dy_min = dy;
            if (i + 1 > max_prec)
                max_prec = i + 1;
        }

        if (tccp->num_resolutions > max_res)
            max_res = tccp->num_resolutions;
    }

    *p_dx_min = dx_min;
    *p_dy_min = dy_min;
    *p_max_prec = max_prec;
    *p_max_res = max_res;
}

void calculate_tile_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                        OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                        OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                        OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 max_prec = 0;
    OPJ_UINT32 max_res = 0;
    OPJ_UINT32 dx_min = 0;
    OPJ_UINT32 dy_min = 0;
    OPJ_UINT32 num_resolutions;
    OPJ_UINT32 num_components = p_image->numcomps;

    for (compno = 0; compno < num_components; ++compno) {
        opj_image_comp_t *comp = &p_image->comps[compno];
        opj_tcp_t *tcp = &p_cp->tcp[compno];
        num_resolutions = tcp->disto_criterion != 0 ? tcp->numresolutions : 1;

        for (resno = 0; resno < num_resolutions; ++resno) {
            opj_tcd_resolution_t *res = &tcp->resolutions[resno];

            if (res->pdx > 0) {
                dx_min = (dx_min == 0) ? res->pdx : OPJ_MIN(dx_min, res->pdx);
            }

            if (res->pdy > 0) {
                dy_min = (dy_min == 0) ? res->pdy : OPJ_MIN(dy_min, res->pdy);
            }

            max_prec = OPJ_MAX(max_prec, resno + 1);
            max_res = OPJ_MAX(max_res, num_resolutions);
        }
    }

    *p_tx0 = (p_tileno % p_image->x0) * p_image->xstep;
    *p_tx1 = (p_tileno % p_image->x0 + 1) * p_image->xstep;
    *p_ty0 = (p_tileno / p_image->x0) * p_image->ystep;
    *p_ty1 = (p_tileno / p_image->x0 + 1) * p_image->ystep;
    *p_dx_min = dx_min;
    *p_dy_min = dy_min;
    *p_max_prec = max_prec;
    *p_max_res = max_res;
}

void calculate_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                   OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                   OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                   OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 max_precision = 0;

    *p_tx0 = p_cp->tx0 + (p_tileno % p_cp->num_tx) * p_cp->tdim_x;
    *p_tx1 = *p_tx0 + p_cp->tdim_x;
    *p_ty0 = p_cp->ty0 + (p_tileno / p_cp->num_tx) * p_cp->tdim_y;
    *p_ty1 = *p_ty0 + p_cp->tdim_y;

    *p_dx_min = 0xFFFFFFFF;
    *p_dy_min = 0xFFFFFFFF;

    for (compno = 0; compno < p_image->numcomps; ++compno) {
        for (resno = 0; resno < p_cp->cp_tx[compno].num_res; ++resno) {
            OPJ_UINT32 dx = p_cp->cp_tx[compno].res_spec[resno].dx;
            OPJ_UINT32 dy = p_cp->cp_tx[compno].res_spec[resno].dy;
            if (dx < *p_dx_min) {
                *p_dx_min = dx;
            }
            if (dy < *p_dy_min) {
                *p_dy_min = dy;
            }
            if (resno + 1 > max_precision) {
                max_precision = resno + 1;
            }
        }
    }

    *p_max_prec = max_precision;
    *p_max_res = p_cp->cp_tx[0].num_res;
}
